import { doc, updateDoc } from "firebase/firestore"; // Firebase функции
import { db } from "../../config/firebaseConfig"; // Конфигурация за Firebase

export async function markAsRead(messageId) {
    try {
        // Получаваме референция към документа в колекцията 'messages' с ID-то messageId
        const messageRef = doc(db, "messages", messageId);

        // Актуализираме документа, като добавяме поле "isRead"
        await updateDoc(messageRef, {
            isRead: true // Маркираме съобщението като прочетено
        });

        return { status: 200 }; // Връщаме успешен отговор
    } catch (error) {
        console.error("Error marking message as read:", error);
        throw new Error("Failed to mark the message as read."); // Извеждаме грешка в случай на проблем
    }
}
